-- Reviewed senior batch 009; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3344,"word":"estimation","meaning":"估計","example":"Our estimation of the wood needed was close to the final amount.","example_zh":"我們估計需要的木材數量，接近最後實際用量。","original_meaning":"估計","original_example":"This is just an estimation of the cost.","original_example_zh":"這只是成本的估算。"},{"source_id":3345,"word":"estrangement","meaning":"疏遠","example":"The old friends' estrangement ended when they began talking again.","example_zh":"老朋友重新交談後，彼此的疏遠結束了。","original_meaning":"疏遠","original_example":"Their estrangement lasted for years.","original_example_zh":"他們的疏遠狀態持續了多年。"},{"source_id":3346,"word":"eternity","meaning":"永恆","example":"Waiting for the late bus felt like an eternity.","example_zh":"等遲到的公車，感覺像過了永遠那麼久。","original_meaning":"永恆","original_example":"The idea of eternity fascinates people.","original_example_zh":"永恆的概念令人著迷。"},{"source_id":3347,"word":"ethics","meaning":"倫理","example":"The debate about sharing test answers raised a question of ethics.","example_zh":"關於分享考試答案的討論，引發倫理問題。","original_meaning":"倫理","original_example":"Medical ethics are important in healthcare.","original_example_zh":"醫療倫理在醫療保健中至關重要。"},{"source_id":3348,"word":"ethnicity","meaning":"族群","example":"The festival welcomed people of every ethnicity.","example_zh":"節慶歡迎每個族群的人參加。","original_meaning":"族群","original_example":"The city has a diverse ethnicity.","original_example_zh":"這座城市的族群構成多元。"},{"source_id":3349,"word":"etiquette","meaning":"禮儀","example":"The host explained the etiquette of greeting guests at the ceremony.","example_zh":"主人說明典禮上迎接客人的禮儀。","original_meaning":"禮儀","original_example":"Proper etiquette is important at formal events.","original_example_zh":"在正式場合，遵守禮儀至關重要。"},{"source_id":3350,"word":"evacuation","meaning":"疏散","example":"The school practiced an orderly evacuation before the storm season.","example_zh":"暴風雨季節前，學校練習有秩序地疏散。","original_meaning":"疏散","original_example":"The evacuation was completed safely.","original_example_zh":"疏散行動已安全完成。"},{"source_id":3351,"word":"evaluation","meaning":"評估","example":"The judges' evaluation considered both strength and appearance.","example_zh":"評審的評估兼顧結構強度與外觀。","original_meaning":"評估","original_example":"The teacher gave an evaluation of my work.","original_example_zh":"老師對我的作業進行了評鑑。"},{"source_id":3352,"word":"evasion","meaning":"逃避","example":"His evasion of the question made the interviewer ask again.","example_zh":"他迴避問題，讓訪談者再次詢問。","original_meaning":"逃避","original_example":"Tax evasion is illegal.","original_example_zh":"逃稅是違法行為。"},{"source_id":3353,"word":"exasperation","meaning":"惱怒","example":"Mina sighed in exasperation when the model wheel came loose again.","example_zh":"模型輪子又鬆脫時，米娜惱怒地嘆氣。","original_meaning":"惱怒","original_example":"His constant complaining caused exasperation.","original_example_zh":"他不斷的抱怨令人惱火。"},{"source_id":3354,"word":"excavation","meaning":"挖掘","example":"The excavation revealed the walls of an ancient house.","example_zh":"挖掘工作揭露了一座古屋的牆基。","original_meaning":"挖掘","original_example":"The excavation revealed ancient ruins.","original_example_zh":"挖掘工作揭露了古代遺跡。"},{"source_id":3355,"word":"excise","meaning":"貨物稅","example":"The lesson used a model fuel station to explain an excise tax.","example_zh":"課程用加油站模型解釋貨物稅。","original_meaning":"貨物稅","original_example":"The government increased excise on alcohol.","original_example_zh":"政府提高了酒類的消費稅。"},{"source_id":3356,"word":"exclusion","meaning":"排斥","example":"The club changed its rules to prevent the exclusion of new students.","example_zh":"社團修改規則，防止新同學受到排斥。","original_meaning":"排斥","original_example":"Social exclusion can harm mental health.","original_example_zh":"社會排斥可能損害心理健康。"},{"source_id":3357,"word":"exertion","meaning":"費力","example":"After the exertion of pushing the cart, we stopped for water.","example_zh":"費力推完車後，我們停下來喝水。","original_meaning":"費力","original_example":"Running a marathon requires great exertion.","original_example_zh":"跑馬拉松需要極大的體力消耗。"},{"source_id":3358,"word":"exodus","meaning":"大批離去","example":"The end of the concert brought an exodus of visitors from the hall.","example_zh":"音樂會結束後，大批觀眾離開大廳。","original_meaning":"大批離去","original_example":"There was a mass exodus from the city.","original_example_zh":"城市發生了大規模遷徙。"},{"source_id":3359,"word":"exonerate","meaning":"免罪","example":"The clear photograph helped exonerate the wrongly accused student.","example_zh":"清楚的照片幫助遭誤指控的學生洗清嫌疑。","original_meaning":"免罪","original_example":"The evidence helped exonerate him.","original_example_zh":"證據幫助他洗清了罪名。"},{"source_id":3360,"word":"expatriate","meaning":"旅外人士","example":"The expatriate returned to her hometown to visit her family.","example_zh":"那位旅外人士回到家鄉探望家人。","original_meaning":"旅外人士","original_example":"Many expatriates live in this city.","original_example_zh":"許多外籍人士居住在這座城市。"},{"source_id":3361,"word":"exploitation","meaning":"剝削","example":"The exhibit described the exploitation of factory workers in the past.","example_zh":"展覽介紹過去工廠工人受到剝削的情形。","original_meaning":"剝削","original_example":"The company was accused of worker exploitation.","original_example_zh":"該公司被指控剝削勞工。"},{"source_id":3362,"word":"exposition","meaning":"展覽會","example":"The science exposition displayed inventions made by local students.","example_zh":"科學展覽會展示當地學生的發明。","original_meaning":"展覽會","original_example":"The museum hosted an art exposition.","original_example_zh":"該博物館舉辦了一場藝術展覽。"},{"source_id":3363,"word":"extortion","meaning":"勒索","example":"The shopkeeper reported the threatening demand for money as extortion.","example_zh":"店主把帶有威脅的索款要求，以勒索事件報案。","original_meaning":"勒索","original_example":"He was arrested for extortion.","original_example_zh":"他因勒索罪被捕。"},{"source_id":3364,"word":"extradition","meaning":"引渡","example":"The history class discussed extradition between two neighboring countries.","example_zh":"歷史課討論兩個鄰國之間的引渡。","original_meaning":"引渡","original_example":"The criminal faced extradition.","original_example_zh":"該名罪犯面臨引渡。"},{"source_id":3365,"word":"extremism","meaning":"極端主義","example":"The textbook contrasted extremism with a willingness to listen to different views.","example_zh":"課本對比極端主義與願意傾聽不同觀點的態度。","original_meaning":"極端主義","original_example":"Extremism can lead to violence.","original_example_zh":"極端主義可能導致暴力。"},{"source_id":3366,"word":"fabrication","meaning":"捏造","example":"The detective discovered that the witness's story was a fabrication.","example_zh":"偵探發現證人的故事是捏造的。","original_meaning":"捏造","original_example":"The report was a fabrication.","original_example_zh":"那份報告是捏造的。"},{"source_id":3367,"word":"facet","meaning":"面向","example":"Learning to repair instruments revealed a new facet of her talent.","example_zh":"學習修理樂器，展現了她才華的新面向。","original_meaning":"面向","original_example":"This issue has many facets.","original_example_zh":"這個問題有許多層面。"},{"source_id":3368,"word":"facsimile","meaning":"傳真；複製本","example":"The museum let us examine a facsimile of the fragile old map.","example_zh":"博物館讓我們查看脆弱古地圖的複製本。","original_meaning":"傳真","original_example":"Please send a facsimile of the document.","original_example_zh":"請傳真該文件的副本。"},{"source_id":3369,"word":"fallout","meaning":"後果","example":"The fallout from the storm included closed roads and damaged roofs.","example_zh":"暴風雨的後果包括道路封閉與屋頂受損。","original_meaning":"後果","original_example":"The fallout affected many families.","original_example_zh":"輻射塵影響了許多家庭。"},{"source_id":3370,"word":"fanaticism","meaning":"狂熱","example":"The coach warned that fanaticism about winning could spoil fair play.","example_zh":"教練提醒，對勝利的狂熱可能破壞公平競賽。","original_meaning":"狂熱","original_example":"His fanaticism worried his friends.","original_example_zh":"他的狂熱令朋友們感到擔憂。"},{"source_id":3371,"word":"fauna","meaning":"動物群","example":"The guide introduced us to the fauna of the wetland.","example_zh":"嚮導向我們介紹濕地的動物群。","original_meaning":"動物群","original_example":"The island is rich in unique fauna.","original_example_zh":"該島擁有豐富的獨特動物群。"},{"source_id":3372,"word":"felony","meaning":"重罪","example":"The courtroom exhibit explained why the serious theft was a felony.","example_zh":"法庭展覽說明那起嚴重竊盜為何屬於重罪。","original_meaning":"重罪","original_example":"He was charged with a felony.","original_example_zh":"他被控犯有重罪。"},{"source_id":3373,"word":"fermentation","meaning":"發酵","example":"Fermentation caused the bread dough to rise in the warm kitchen.","example_zh":"發酵讓麵糰在溫暖廚房裡膨脹。","original_meaning":"發酵","original_example":"Fermentation is used to make wine.","original_example_zh":"發酵是用來釀造葡萄酒的。"},{"source_id":3374,"word":"fertility","meaning":"肥沃","example":"Compost improved the fertility of the soil in our garden.","example_zh":"堆肥改善了我們花園土壤的肥沃程度。","original_meaning":"肥沃","original_example":"Soil fertility is essential for crops.","original_example_zh":"土壤肥力對作物至關重要。"},{"source_id":3375,"word":"feudalism","meaning":"封建制度","example":"The history model showed how feudalism linked land, service, and power.","example_zh":"歷史模型展示封建制度如何連結土地、服役與權力。","original_meaning":"封建制度","original_example":"Feudalism shaped medieval society.","original_example_zh":"封建主義塑造了中世紀社會。"},{"source_id":3376,"word":"fiasco","meaning":"慘敗","example":"The outdoor play became a fiasco when the scenery collapsed in the rain.","example_zh":"舞台布景在雨中倒下，讓戶外戲劇演出變成一場慘敗。","original_meaning":"慘敗","original_example":"The event turned into a complete fiasco.","original_example_zh":"這場活動徹底淪為一場災難。"},{"source_id":3377,"word":"fidelity","meaning":"忠誠；保真度","example":"The recording reproduced the violin's sound with remarkable fidelity.","example_zh":"錄音以驚人的保真度重現小提琴音色。","original_meaning":"忠誠","original_example":"Loyalty is a sign of fidelity.","original_example_zh":"忠誠是忠貞的象徵。"},{"source_id":3378,"word":"figurehead","meaning":"名義領袖","example":"In the story, the king was only a figurehead while the council made decisions.","example_zh":"故事裡，國王只是名義領袖，實際決策由委員會作出。","original_meaning":"名義領袖","original_example":"He was only a figurehead leader.","original_example_zh":"他只是一個傀儡領袖。"},{"source_id":3379,"word":"filibuster","meaning":"冗長演說","example":"The history lesson described a filibuster that delayed the vote.","example_zh":"歷史課介紹一場拖延表決的冗長演說。","original_meaning":"冗長演說","original_example":"The senator used a filibuster tactic.","original_example_zh":"參議員使用了阻撓議事戰術。"},{"source_id":3380,"word":"firmware","meaning":"韌體","example":"The technician updated the camera's firmware to fix a small glitch.","example_zh":"技師更新相機韌體，修正一個小故障。","original_meaning":"韌體","original_example":"Update the firmware before using the device.","original_example_zh":"使用裝置前請先更新韌體。"},{"source_id":3381,"word":"fission","meaning":"裂變","example":"The teacher used colored balls to model nuclear fission.","example_zh":"老師用彩球模擬核分裂。","original_meaning":"裂變","original_example":"Nuclear fission produces energy.","original_example_zh":"核裂變會產生能量。"},{"source_id":3382,"word":"flora","meaning":"植物群","example":"The students recorded the flora along the mountain trail.","example_zh":"學生記錄山徑沿線的植物群。","original_meaning":"植物群","original_example":"The region has diverse flora.","original_example_zh":"該地區擁有多樣的植物群。"},{"source_id":3383,"word":"fluctuation","meaning":"波動","example":"The fluctuation in water level was clear from the marks on the stone wall.","example_zh":"從石牆上的水痕，可以看出水位的波動。","original_meaning":"波動","original_example":"Stock prices show constant fluctuation.","original_example_zh":"股價呈現持續波動。"},{"source_id":3384,"word":"fluorescent","meaning":"螢光的","example":"The fluorescent mineral glowed under the museum's special light.","example_zh":"螢光礦物在博物館的特殊光照下發亮。","original_meaning":"螢光的","original_example":"The room was lit by fluorescent lights.","original_example_zh":"房間裡亮著螢光燈。"},{"source_id":3385,"word":"folklore","meaning":"民間傳說","example":"Grandmother shared folklore about the old mountain village.","example_zh":"祖母分享關於古老山村的民間傳說。","original_meaning":"民間傳說","original_example":"The story is based on folklore.","original_example_zh":"這個故事改編自民間傳說。"},{"source_id":3386,"word":"footprint","meaning":"足跡","example":"A small footprint in the mud showed where the puppy had walked.","example_zh":"泥地裡的小腳印顯示小狗走過的地方。","original_meaning":"足跡","original_example":"The animal left a footprint in the sand.","original_example_zh":"那隻動物在沙地上留下了腳印。"},{"source_id":3387,"word":"forerunner","meaning":"先驅","example":"The wooden glider was a forerunner of the modern model aircraft.","example_zh":"這架木製滑翔機是現代模型飛機的前身。","original_meaning":"先驅","original_example":"She is a forerunner in her field.","original_example_zh":"她是該領域的先驅。"},{"source_id":3388,"word":"foresight","meaning":"遠見","example":"Her foresight in packing spare batteries saved the night walk.","example_zh":"她有遠見地多帶電池，讓夜間健行得以順利進行。","original_meaning":"遠見","original_example":"His foresight helped the company succeed.","original_example_zh":"他的遠見幫助公司取得成功。"},{"source_id":3389,"word":"forestry","meaning":"林業","example":"The class learned how forestry can balance timber use with forest renewal.","example_zh":"班上學習林業如何兼顧木材利用與森林更新。","original_meaning":"林業","original_example":"Forestry is important for the environment.","original_example_zh":"林業對環境很重要。"},{"source_id":3390,"word":"forgery","meaning":"偽造","example":"The expert identified the painting as a forgery by examining its materials.","example_zh":"專家檢查材料後，判定那幅畫是偽作。","original_meaning":"偽造","original_example":"The painting was revealed as a forgery.","original_example_zh":"那幅畫被證實是贗品。"},{"source_id":3391,"word":"formation","meaning":"形成","example":"The students observed the formation of crystals in the container.","example_zh":"學生觀察容器裡晶體的形成。","original_meaning":"形成","original_example":"Cloud formation depends on temperature.","original_example_zh":"雲的形成取決於溫度。"},{"source_id":3392,"word":"fortress","meaning":"堡壘","example":"The ancient fortress stood above the narrow valley.","example_zh":"古老堡壘矗立在狹窄山谷上方。","original_meaning":"堡壘","original_example":"The fortress was built centuries ago.","original_example_zh":"這座堡壘建於數世紀前。"},{"source_id":3393,"word":"fracture","meaning":"骨折","example":"The doctor used the image to explain the small fracture in his arm.","example_zh":"醫師用影像說明他手臂上的小骨折。","original_meaning":"骨折","original_example":"He suffered a bone fracture.","original_example_zh":"他遭受了骨折。"},{"source_id":3394,"word":"fragmentation","meaning":"碎片化","example":"The landscape model showed the fragmentation of a once-connected forest.","example_zh":"地景模型呈現原本相連的森林如何碎片化。","original_meaning":"碎片化","original_example":"The fragmentation of data caused errors.","original_example_zh":"資料的碎片化導致了錯誤。"},{"source_id":3395,"word":"fraud","meaning":"詐騙","example":"The bank warned customers about fraud involving fake messages.","example_zh":"銀行提醒顧客注意利用假訊息進行的詐騙。","original_meaning":"詐騙","original_example":"He was arrested for fraud.","original_example_zh":"他因詐欺罪被逮捕。"},{"source_id":3396,"word":"freelance","meaning":"自由接案的","example":"The freelance illustrator worked on book pictures from her home studio.","example_zh":"自由接案插畫家在家中工作室繪製書中插圖。","original_meaning":"自由接案的","original_example":"She works as a freelance designer.","original_example_zh":"她擔任自由設計師。"},{"source_id":3397,"word":"freight","meaning":"貨物","example":"The freight train carried timber and grain through the valley.","example_zh":"貨運列車載著木材與穀物穿過山谷。","original_meaning":"貨物","original_example":"The ship carried heavy freight.","original_example_zh":"那艘船載著沉重的貨物。"},{"source_id":3398,"word":"frenzy","meaning":"瘋狂","example":"The sudden shower sent the market into a frenzy of hurried packing.","example_zh":"突如其來的雨，讓市場陷入匆忙收攤的混亂。","original_meaning":"瘋狂","original_example":"Fans were in a frenzy at the concert.","original_example_zh":"演唱會上粉絲們陷入狂熱。"},{"source_id":3399,"word":"frivolous","meaning":"輕浮的","example":"The team avoided frivolous purchases and saved money for useful tools.","example_zh":"小組避免輕率的花費，把錢存來買實用工具。","original_meaning":"輕浮的","original_example":"His comment sounded frivolous.","original_example_zh":"他的評論聽起來很輕浮。"},{"source_id":3400,"word":"fugitive","meaning":"逃犯","example":"The detective novel followed a fugitive who was eventually found.","example_zh":"那本偵探小說追蹤一名最終被找到的逃犯。","original_meaning":"逃犯","original_example":"The police caught the fugitive.","original_example_zh":"警方抓到了逃犯。"},{"source_id":3401,"word":"fundamentalism","meaning":"基本教義派","example":"The history class discussed fundamentalism and strict readings of religious texts.","example_zh":"歷史課討論基本教義派及對宗教經典的嚴格解讀。","original_meaning":"基本教義派","original_example":"Fundamentalism influences certain beliefs.","original_example_zh":"原教旨主義影響某些信仰。"},{"source_id":3402,"word":"fusion","meaning":"融合","example":"The performance was a fusion of classical music and folk dance.","example_zh":"這場演出融合了古典音樂與民俗舞蹈。","original_meaning":"融合","original_example":"The fusion of cultures created something unique.","original_example_zh":"文化的融合創造了獨一無二的事物。"},{"source_id":3403,"word":"futility","meaning":"徒勞","example":"The futility of repairing the shattered cup made us choose a new one.","example_zh":"修補碎裂杯子徒勞無功，讓我們決定換一個新的。","original_meaning":"徒勞","original_example":"They realized the futility of arguing.","original_example_zh":"他們意識到爭論是徒勞的。"},{"source_id":3404,"word":"gadget","meaning":"小裝置","example":"The small gadget helped us measure soil moisture in the garden.","example_zh":"這個小裝置幫我們測量菜園的土壤濕度。","original_meaning":"小裝置","original_example":"This gadget makes life easier.","original_example_zh":"這個小工具讓生活更輕鬆。"},{"source_id":3405,"word":"galvanize","meaning":"激勵","example":"The first successful launch helped galvanize the model-rocket team.","example_zh":"第一次發射成功，激勵了模型火箭小組。","original_meaning":"激勵","original_example":"The speech helped galvanize public support.","original_example_zh":"這場演說有助於激發公眾支持。"},{"source_id":3406,"word":"gazette","meaning":"公報","example":"The town gazette announced the opening of the new library.","example_zh":"城鎮公報宣布新圖書館開幕。","original_meaning":"公報","original_example":"The notice was published in the official gazette.","original_example_zh":"該公告刊登於官方公報。"},{"source_id":3407,"word":"genealogy","meaning":"系譜","example":"The family used old photographs to explore its genealogy.","example_zh":"家人用老照片探索家族系譜。","original_meaning":"系譜","original_example":"He studied his family genealogy.","original_example_zh":"他研究了自己的家族譜系。"},{"source_id":3408,"word":"generalization","meaning":"概括","example":"The teacher warned that one example was not enough for a broad generalization.","example_zh":"老師提醒，一個例子不足以作出廣泛概括。","original_meaning":"概括","original_example":"Avoid making broad generalizations.","original_example_zh":"避免過度概括。"},{"source_id":3409,"word":"genesis","meaning":"起源","example":"The old sketch revealed the genesis of the artist's famous design.","example_zh":"舊草圖揭示藝術家著名設計的起源。","original_meaning":"起源","original_example":"The project marked the genesis of a new era.","original_example_zh":"該計畫標誌著新時代的開端。"},{"source_id":3410,"word":"genetically","meaning":"在基因上；以基因方式","example":"The study compared genetically related plants from two valleys.","example_zh":"研究比較來自兩處山谷、基因相關的植物。","original_meaning":"基因地","original_example":"The disease is genetically inherited.","original_example_zh":"這種疾病是遺傳性的。"},{"source_id":3411,"word":"genocide","meaning":"種族滅絕","example":"The memorial honored the victims of genocide.","example_zh":"紀念館悼念種族滅絕的受害者。","original_meaning":"種族滅絕","original_example":"The war resulted in genocide.","original_example_zh":"那場戰爭導致了種族滅絕。"},{"source_id":3412,"word":"genome","meaning":"基因組","example":"The classroom model represented the genome as a complete set of genetic instructions.","example_zh":"教室模型把基因組呈現為一套完整的遺傳訊息。","original_meaning":"基因組","original_example":"Scientists mapped the human genome.","original_example_zh":"科學家繪製了人類基因組圖譜。"},{"source_id":3413,"word":"geopolitical","meaning":"地緣政治的","example":"The lesson examined the geopolitical importance of the narrow sea passage.","example_zh":"課程探討狹窄海峽在地緣政治上的重要性。","original_meaning":"地緣政治的","original_example":"Geopolitical tensions are rising.","original_example_zh":"地緣政治緊張局勢正在升高。"},{"source_id":3414,"word":"geothermal","meaning":"地熱的","example":"The town used geothermal heat to warm its public greenhouse.","example_zh":"城鎮使用地熱為公共溫室保暖。","original_meaning":"地熱的","original_example":"The area uses geothermal energy.","original_example_zh":"該地區利用地熱能。"},{"source_id":3415,"word":"gimmick","meaning":"花招","example":"The bright spinning display was a gimmick to draw people to the stall.","example_zh":"鮮亮旋轉展示是吸引人靠近攤位的花招。","original_meaning":"花招","original_example":"The advertisement was just a gimmick.","original_example_zh":"那則廣告只是噱頭。"},{"source_id":3416,"word":"glacier","meaning":"冰川","example":"The glacier moved slowly through the high mountain valley.","example_zh":"冰川緩慢穿過高山山谷。","original_meaning":"冰川","original_example":"The glacier is melting due to climate change.","original_example_zh":"由於氣候變遷，冰川正在融化。"},{"source_id":3417,"word":"globalization","meaning":"全球化","example":"The market's imported foods offered a glimpse of globalization.","example_zh":"市場裡的進口食物，讓人一窺全球化。","original_meaning":"全球化","original_example":"Globalization connects economies worldwide.","original_example_zh":"全球化將世界各地的經濟體連結起來。"},{"source_id":3418,"word":"governance","meaning":"治理","example":"Good governance helped the club manage donations fairly.","example_zh":"良好治理讓社團能公平管理捐款。","original_meaning":"治理","original_example":"Effective governance is crucial for stability.","original_example_zh":"有效的治理對穩定至關重要。"},{"source_id":3419,"word":"gradient","meaning":"梯度；坡度","example":"The trail's steep gradient made the final climb tiring.","example_zh":"步道陡峭的坡度，讓最後一段攀爬很費力。","original_meaning":"梯度","original_example":"The slope has a steep gradient.","original_example_zh":"斜坡坡度很陡。"},{"source_id":3420,"word":"grandeur","meaning":"壯觀","example":"The grandeur of the old theater left the visitors amazed.","example_zh":"老劇院的壯觀讓參觀者驚嘆。","original_meaning":"壯觀","original_example":"The palace showed great grandeur.","original_example_zh":"宮殿氣勢恢宏。"},{"source_id":3421,"word":"grassroots","meaning":"草根的","example":"The grassroots campaign began with neighbors cleaning their own street.","example_zh":"這場草根運動從鄰居一起清掃自家街道開始。","original_meaning":"草根的","original_example":"Grassroots movements drive social change.","original_example_zh":"草根運動推動社會變革。"},{"source_id":3422,"word":"gratification","meaning":"滿足","example":"Finishing the difficult model brought a deep sense of gratification.","example_zh":"完成困難模型，帶來深深的滿足感。","original_meaning":"滿足","original_example":"She felt deep gratification after helping others.","original_example_zh":"幫助他人後，她感到深深的滿足。"},{"source_id":3423,"word":"gravitation","meaning":"重力","example":"The teacher used a globe and a falling ball to introduce gravitation.","example_zh":"老師用地球儀與落球介紹重力。","original_meaning":"重力","original_example":"Gravitation keeps planets in orbit.","original_example_zh":"引力使行星保持在軌道上。"},{"source_id":3424,"word":"greenhouse","meaning":"溫室","example":"The greenhouse kept the young plants warm during the cold week.","example_zh":"寒冷的一週裡，溫室讓幼苗保持溫暖。","original_meaning":"溫室","original_example":"Plants grow well in a greenhouse.","original_example_zh":"植物在溫室裡生長良好。"},{"source_id":3425,"word":"grievance","meaning":"不滿","example":"The captain listened to each teammate's grievance before changing the schedule.","example_zh":"隊長先傾聽每位隊友的不滿，再調整練習時間表。","original_meaning":"不滿","original_example":"Workers voiced their grievances.","original_example_zh":"工人們表達了他們的怨言。"},{"source_id":3426,"word":"guerrilla","meaning":"游擊隊","example":"The museum displayed equipment once used by a guerrilla.","example_zh":"博物館展示一位游擊隊員曾使用的裝備。","original_meaning":"游擊隊","original_example":"The guerrilla fighters hid in the forest.","original_example_zh":"游擊隊員藏身於森林中。"},{"source_id":3427,"word":"guideline","meaning":"準則","example":"The safety guideline helped us arrange the workshop tools correctly.","example_zh":"安全準則幫助我們正確擺放工坊工具。","original_meaning":"準則","original_example":"Follow the safety guidelines carefully.","original_example_zh":"請仔細遵循安全指南。"},{"source_id":3428,"word":"hallmark","meaning":"特質","example":"Careful craftsmanship was the hallmark of the old violin maker's work.","example_zh":"細緻手藝是那位老提琴製作師作品的特色。","original_meaning":"特質","original_example":"Honesty is a hallmark of good character.","original_example_zh":"誠實是良好品格的標誌。"},{"source_id":3429,"word":"hallucination","meaning":"幻覺","example":"The novel described a traveler's hallucination of a companion who was not really there.","example_zh":"小說描寫旅人產生幻覺，看見其實不在身旁的同伴。","original_meaning":"幻覺","original_example":"The patient experienced hallucinations.","original_example_zh":"該患者出現了幻覺。"},{"source_id":3430,"word":"hasten","meaning":"加速","example":"The approaching rain made us hasten back to the shelter.","example_zh":"雨勢即將到來，讓我們加快腳步返回避雨處。","original_meaning":"加速","original_example":"We must hasten the process.","original_example_zh":"我們必須加快進度。"},{"source_id":3431,"word":"havoc","meaning":"浩劫","example":"The wind caused havoc among the empty market stalls.","example_zh":"強風把空的市場攤位吹得一團亂。","original_meaning":"浩劫","original_example":"The storm caused great havoc.","original_example_zh":"風暴造成巨大破壞。"},{"source_id":3432,"word":"hazardous","meaning":"危險的","example":"The broken railing made the old path hazardous.","example_zh":"破損護欄讓老步道變得危險。","original_meaning":"危險的","original_example":"Handling chemicals can be hazardous.","original_example_zh":"處理化學品可能有危險。"},{"source_id":3433,"word":"hegemony","meaning":"霸權","example":"The class examined a powerful kingdom's hegemony over nearby states.","example_zh":"班上研究強大王國對鄰近邦國的霸權。","original_meaning":"霸權","original_example":"The empire maintained its hegemony.","original_example_zh":"帝國維持了其霸權。"},{"source_id":3434,"word":"herbicide","meaning":"除草劑","example":"The gardener stored the herbicide in a locked cabinet away from food.","example_zh":"園丁把除草劑收在遠離食物的上鎖櫃子裡。","original_meaning":"除草劑","original_example":"Farmers used herbicide to kill weeds.","original_example_zh":"農民使用除草劑來殺死雜草。"},{"source_id":3435,"word":"hereditary","meaning":"遺傳的","example":"The class used a family tree to discuss hereditary traits.","example_zh":"班上使用家族樹討論遺傳特徵。","original_meaning":"遺傳的","original_example":"Some diseases are hereditary.","original_example_zh":"有些疾病是遺傳性的。"},{"source_id":3436,"word":"hindrance","meaning":"障礙","example":"The fallen tree was a hindrance to anyone using the narrow trail.","example_zh":"倒樹是所有使用狹窄步道者的障礙。","original_meaning":"障礙","original_example":"Lack of funds was a major hindrance.","original_example_zh":"資金短缺是主要障礙。"},{"source_id":3437,"word":"holistic","meaning":"全面的","example":"The teacher took a holistic view of the project, considering people and nature.","example_zh":"老師從全面角度看專題，把人與自然都納入考量。","original_meaning":"全面的","original_example":"He follows a holistic approach to health.","original_example_zh":"他採取整體健康法。"},{"source_id":3438,"word":"homage","meaning":"敬意","example":"The students performed the old song as an homage to their music teacher.","example_zh":"學生演奏老歌，向音樂老師致敬。","original_meaning":"敬意","original_example":"The film paid homage to classic cinema.","original_example_zh":"這部電影向經典電影致敬。"},{"source_id":3439,"word":"homestead","meaning":"家園","example":"The family's homestead included a cottage, orchard, and vegetable patch.","example_zh":"這家人的家園有小屋、果園與菜圃。","original_meaning":"家園","original_example":"They lived on a rural homestead.","original_example_zh":"他們住在鄉間農舍。"},{"source_id":3440,"word":"homogeneous","meaning":"同質的","example":"The well-mixed paint formed a homogeneous color throughout the bowl.","example_zh":"充分攪拌的顏料，在整個碗裡呈現均勻一致的顏色。","original_meaning":"同質的","original_example":"The mixture became homogeneous.","original_example_zh":"混合物變得均勻。"},{"source_id":3441,"word":"humility","meaning":"謙遜","example":"The winning violinist showed humility by thanking everyone who helped her.","example_zh":"獲勝的小提琴家感謝所有幫助她的人，展現謙遜。","original_meaning":"謙遜","original_example":"She showed humility despite success.","original_example_zh":"儘管成功，她仍展現出謙遜。"},{"source_id":3442,"word":"hydroelectric","meaning":"水力發電的","example":"The model showed how flowing water can power a hydroelectric generator.","example_zh":"模型展示流動的水如何驅動水力發電機。","original_meaning":"水力發電的","original_example":"Hydroelectric power is renewable.","original_example_zh":"水力發電是可再生能源。"},{"source_id":3443,"word":"hypertension","meaning":"高血壓","example":"The nurse measured his blood pressure during a routine check for hypertension.","example_zh":"護理師在高血壓例行檢查時，測量他的血壓。","original_meaning":"高血壓","original_example":"He suffers from hypertension.","original_example_zh":"他患有高血壓。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-estimation-01-v1","level":"senior","word":"estimation","sort_order":1,"sense":"估計","alt_zh":"高中生把事先備好的木料與完成鳥屋旁少量剩料作比較。","example":"Our estimation of the wood needed was close to the final amount.","example_zh":"我們估計需要的木材數量，接近最後實際用量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/estimation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-estrangement-01-v1","level":"senior","word":"estrangement","sort_order":1,"sense":"疏遠","alt_zh":"兩名曾疏遠的成年老朋友在花園長椅上重新微笑交談。","example":"The old friends' estrangement ended when they began talking again.","example_zh":"老朋友重新交談後，彼此的疏遠結束了。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/estrangement-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-eternity-01-v1","level":"senior","word":"eternity","sort_order":1,"sense":"永恆","alt_zh":"高中生在安全公車站反覆看指針手錶，遠處公車還沒到。","example":"Waiting for the late bus felt like an eternity.","example_zh":"等遲到的公車，感覺像過了永遠那麼久。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/eternity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ethics-01-v1","level":"senior","word":"ethics","sort_order":1,"sense":"倫理","alt_zh":"高中生在教室討論公平應試，老師傾聽，有人把答案紙收好不給抄。","example":"The debate about sharing test answers raised a question of ethics.","example_zh":"關於分享考試答案的討論，引發倫理問題。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ethics-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ethnicity-01-v1","level":"senior","word":"ethnicity","sort_order":1,"sense":"族群","alt_zh":"不同背景的家庭與高中生穿日常服裝，在友善社區節慶分享食物與音樂。","example":"The festival welcomed people of every ethnicity.","example_zh":"節慶歡迎每個族群的人參加。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ethnicity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-etiquette-01-v1","level":"senior","word":"etiquette","sort_order":1,"sense":"禮儀","alt_zh":"成年主人向高中志工示範微笑迎接、禮貌引導來賓入座。","example":"The host explained the etiquette of greeting guests at the ceremony.","example_zh":"主人說明典禮上迎接客人的禮儀。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/etiquette-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-evacuation-01-v1","level":"senior","word":"evacuation","sort_order":1,"sense":"疏散","alt_zh":"老師帶高中生沿安全通道依序離開校舍，到開闊集合區。","example":"The school practiced an orderly evacuation before the storm season.","example_zh":"暴風雨季節前，學校練習有秩序地疏散。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/evacuation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-evaluation-01-v1","level":"senior","word":"evaluation","sort_order":1,"sense":"評估","alt_zh":"成年評審仔細比較高中生的模型橋，檢查支撐結構與整齊外觀。","example":"The judges' evaluation considered both strength and appearance.","example_zh":"評審的評估兼顧結構強度與外觀。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/evaluation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-evasion-01-v1","level":"senior","word":"evasion","sort_order":1,"sense":"逃避","alt_zh":"成年受訪者轉頭含糊回應，訪談者耐心重新提出問題。","example":"His evasion of the question made the interviewer ask again.","example_zh":"他迴避問題，讓訪談者再次詢問。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/evasion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exasperation-01-v1","level":"senior","word":"exasperation","sort_order":1,"sense":"惱怒","alt_zh":"高中女生皺眉看著再度脫落的模型車輪，同伴在旁準備協助。","example":"Mina sighed in exasperation when the model wheel came loose again.","example_zh":"模型輪子又鬆脫時，米娜惱怒地嘆氣。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exasperation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-excavation-01-v1","level":"senior","word":"excavation","sort_order":1,"sense":"挖掘","alt_zh":"考古學家與受指導的高中生用小刷子清理，露出古屋石牆基礎。","example":"The excavation revealed the walls of an ancient house.","example_zh":"挖掘工作揭露了一座古屋的牆基。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/excavation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-excise-01-v1","level":"senior","word":"excise","sort_order":1,"sense":"貨物稅","alt_zh":"老師在桌上加油站模型旁，用硬幣分堆說明商品價格中的稅，無數字文字。","example":"The lesson used a model fuel station to explain an excise tax.","example_zh":"課程用加油站模型解釋貨物稅。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/excise-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exclusion-01-v1","level":"senior","word":"exclusion","sort_order":1,"sense":"排斥","alt_zh":"高中社團主動挪出座位，微笑歡迎原本站在一旁的新同學加入。","example":"The club changed its rules to prevent the exclusion of new students.","example_zh":"社團修改規則，防止新同學受到排斥。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exclusion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exertion-01-v1","level":"senior","word":"exertion","sort_order":1,"sense":"費力","alt_zh":"高中生把裝滿物資的推車推到平地後，擦汗喝水休息。","example":"After the exertion of pushing the cart, we stopped for water.","example_zh":"費力推完車後，我們停下來喝水。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exertion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exodus-01-v1","level":"senior","word":"exodus","sort_order":1,"sense":"大批離去","alt_zh":"演出結束後，成年觀眾與家庭沿寬敞出口有序離開音樂廳。","example":"The end of the concert brought an exodus of visitors from the hall.","example_zh":"音樂會結束後，大批觀眾離開大廳。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exodus-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exonerate-01-v1","level":"senior","word":"exonerate","sort_order":1,"sense":"免罪","alt_zh":"老師查看照片，發現被誤會的高中生其實在幫忙收拾，向他溫和說明。","example":"The clear photograph helped exonerate the wrongly accused student.","example_zh":"清楚的照片幫助遭誤指控的學生洗清嫌疑。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exonerate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-expatriate-01-v1","level":"senior","word":"expatriate","sort_order":1,"sense":"旅外人士","alt_zh":"成年旅外女子帶著行李在家門口擁抱久未見面的家人。","example":"The expatriate returned to her hometown to visit her family.","example_zh":"那位旅外人士回到家鄉探望家人。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/expatriate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exploitation-01-v1","level":"senior","word":"exploitation","sort_order":1,"sense":"剝削","alt_zh":"高中生在博物館看歷史工廠成年工人長時間辛勞的模型，無傷害或虐待。","example":"The exhibit described the exploitation of factory workers in the past.","example_zh":"展覽介紹過去工廠工人受到剝削的情形。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exploitation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exposition-01-v1","level":"senior","word":"exposition","sort_order":1,"sense":"展覽會","alt_zh":"高中生在科學展覽會各攤位展示機器人、水輪與簡單模型發明。","example":"The science exposition displayed inventions made by local students.","example_zh":"科學展覽會展示當地學生的發明。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exposition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-extortion-01-v1","level":"senior","word":"extortion","sort_order":1,"sense":"勒索","alt_zh":"成年店主在警局把無可辨識文字的威脅信交給警員，氣氛莊重，無暴力。","example":"The shopkeeper reported the threatening demand for money as extortion.","example_zh":"店主把帶有威脅的索款要求，以勒索事件報案。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/extortion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-extradition-01-v1","level":"senior","word":"extradition","sort_order":1,"sense":"引渡","alt_zh":"教室裡，老師以兩個虛構國家的地圖模型與成年人法律文件解說司法合作，無拘束器具。","example":"The history class discussed extradition between two neighboring countries.","example_zh":"歷史課討論兩個鄰國之間的引渡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/extradition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-extremism-01-v1","level":"senior","word":"extremism","sort_order":1,"sense":"極端主義","alt_zh":"高中生在老師帶領下冷靜討論不同意見，一人抱臂拒聽、其他人平和交流，無標語。","example":"The textbook contrasted extremism with a willingness to listen to different views.","example_zh":"課本對比極端主義與願意傾聽不同觀點的態度。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/extremism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fabrication-01-v1","level":"senior","word":"fabrication","sort_order":1,"sense":"捏造","alt_zh":"成年偵探把故事中的描述與不相符的照片比對，證人神情不安。","example":"The detective discovered that the witness's story was a fabrication.","example_zh":"偵探發現證人的故事是捏造的。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fabrication-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-facet-01-v1","level":"senior","word":"facet","sort_order":1,"sense":"面向","alt_zh":"高中女生除了拉提琴，也在老師旁細心修復樂器，同學驚喜欣賞。","example":"Learning to repair instruments revealed a new facet of her talent.","example_zh":"學習修理樂器，展現了她才華的新面向。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/facet-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-facsimile-01-v1","level":"senior","word":"facsimile","sort_order":1,"sense":"傳真；複製本","alt_zh":"高中生在桌上查看古地圖的完整複製本，原件受到玻璃櫃保護，無文字。","example":"The museum let us examine a facsimile of the fragile old map.","example_zh":"博物館讓我們查看脆弱古地圖的複製本。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/facsimile-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fallout-01-v1","level":"senior","word":"fallout","sort_order":1,"sense":"後果","alt_zh":"暴風雨後，村道被安全封閉，成年工人查看幾間受損空屋的屋頂。","example":"The fallout from the storm included closed roads and damaged roofs.","example_zh":"暴風雨的後果包括道路封閉與屋頂受損。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fallout-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fanaticism-01-v1","level":"senior","word":"fanaticism","sort_order":1,"sense":"狂熱","alt_zh":"教練平靜勸導過度激動的成年球員，其他隊員等待公平繼續比賽。","example":"The coach warned that fanaticism about winning could spoil fair play.","example_zh":"教練提醒，對勝利的狂熱可能破壞公平競賽。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fanaticism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fauna-01-v1","level":"senior","word":"fauna","sort_order":1,"sense":"動物群","alt_zh":"高中生在安全步道欣賞同一濕地中的水鳥、青蛙、魚與蜻蜓。","example":"The guide introduced us to the fauna of the wetland.","example_zh":"嚮導向我們介紹濕地的動物群。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fauna-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-felony-01-v1","level":"senior","word":"felony","sort_order":1,"sense":"重罪","alt_zh":"高中生在司法博物館看重大藝術品竊案的模擬法庭展覽，無犯罪方法細節。","example":"The courtroom exhibit explained why the serious theft was a felony.","example_zh":"法庭展覽說明那起嚴重竊盜為何屬於重罪。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/felony-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fermentation-01-v1","level":"senior","word":"fermentation","sort_order":1,"sense":"發酵","alt_zh":"老師與高中生觀察透明碗中的麵糰膨起，裡面可見細小氣泡。","example":"Fermentation caused the bread dough to rise in the warm kitchen.","example_zh":"發酵讓麵糰在溫暖廚房裡膨脹。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fermentation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fertility-01-v1","level":"senior","word":"fertility","sort_order":1,"sense":"肥沃","alt_zh":"高中生把深色成熟堆肥混入菜園表土，附近蔬菜健康茂盛。","example":"Compost improved the fertility of the soil in our garden.","example_zh":"堆肥改善了我們花園土壤的肥沃程度。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fertility-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-feudalism-01-v1","level":"senior","word":"feudalism","sort_order":1,"sense":"封建制度","alt_zh":"高中生觀察博物館中的城堡、莊園與成年歷史人物模型，老師客觀解說。","example":"The history model showed how feudalism linked land, service, and power.","example_zh":"歷史模型展示封建制度如何連結土地、服役與權力。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/feudalism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fiasco-01-v1","level":"senior","word":"fiasco","sort_order":1,"sense":"慘敗","alt_zh":"演出已安全暫停，高中劇團站在屋簷下，看著雨中倒下的輕型紙布景，無傷者。","example":"The outdoor play became a fiasco when the scenery collapsed in the rain.","example_zh":"舞台布景在雨中倒下，讓戶外戲劇演出變成一場慘敗。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fiasco-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fidelity-01-v1","level":"senior","word":"fidelity","sort_order":1,"sense":"忠誠；保真度","alt_zh":"成年錄音師與高中提琴手戴耳機仔細聆聽，旁邊螢幕只有波形無文字。","example":"The recording reproduced the violin's sound with remarkable fidelity.","example_zh":"錄音以驚人的保真度重現小提琴音色。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fidelity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-figurehead-01-v1","level":"senior","word":"figurehead","sort_order":1,"sense":"名義領袖","alt_zh":"虛構歷史宮廷中，成年國王坐在儀式王座，旁邊成年委員圍桌處理決策文件。","example":"In the story, the king was only a figurehead while the council made decisions.","example_zh":"故事裡，國王只是名義領袖，實際決策由委員會作出。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/figurehead-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-filibuster-01-v1","level":"senior","word":"filibuster","sort_order":1,"sense":"冗長演說","alt_zh":"成年議員在歷史議會場景中持續演說，其他成年議員疲倦等候，無政黨標誌。","example":"The history lesson described a filibuster that delayed the vote.","example_zh":"歷史課介紹一場拖延表決的冗長演說。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/filibuster-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-firmware-01-v1","level":"senior","word":"firmware","sort_order":1,"sense":"韌體","alt_zh":"成年技師把相機連接電腦，螢幕顯示簡單無字進度圖示。","example":"The technician updated the camera's firmware to fix a small glitch.","example_zh":"技師更新相機韌體，修正一個小故障。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/firmware-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fission-01-v1","level":"senior","word":"fission","sort_order":1,"sense":"裂變","alt_zh":"科學老師以彩球構成的原子核模型，向高中生展示一個原子核分成兩部分的概念，無設備細節。","example":"The teacher used colored balls to model nuclear fission.","example_zh":"老師用彩球模擬核分裂。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fission-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-flora-01-v1","level":"senior","word":"flora","sort_order":1,"sense":"植物群","alt_zh":"高中生觀察並描繪山徑旁不同種類的花、草、蕨類與灌木。","example":"The students recorded the flora along the mountain trail.","example_zh":"學生記錄山徑沿線的植物群。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/flora-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fluctuation-01-v1","level":"senior","word":"fluctuation","sort_order":1,"sense":"波動","alt_zh":"高中生在安全河岸比較石牆高低不同的舊水痕與當前水面。","example":"The fluctuation in water level was clear from the marks on the stone wall.","example_zh":"從石牆上的水痕，可以看出水位的波動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fluctuation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fluorescent-01-v1","level":"senior","word":"fluorescent","sort_order":1,"sense":"螢光的","alt_zh":"高中生在博物館安全展示櫃前，看礦物在特殊照明下呈現明亮螢光。","example":"The fluorescent mineral glowed under the museum's special light.","example_zh":"螢光礦物在博物館的特殊光照下發亮。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fluorescent-01-v1.webp","local_path":"","style":"